// Scope projection only. Taxes are calculated once by the existing full-income engine.
import {calculatePlan,comparePlan,comparePresetsPlan,exportIntegrated} from './integrated.js';
import {sum,TYPES,defaults,years} from './engine.js';
import {normalizeSimpleState} from './policy.js';
export const BONUS_TYPES=['opi1','opi2','settlement'];
export const SETTLEMENT_NOTICE='49.5% 선징수와 지급연도 소득 귀속은 사용자가 2026년 10월 7일 전달한 회사 안내를 채택한 모델 기준입니다. 지급일만으로 모든 성과급의 소득 귀속을 단정하지 않습니다. 세금 정산은 소득세·지방소득세를 포함한 상여 비례배분 추정 차액이며 실제 전체 연말정산 환급액과 다릅니다. 개인 공제·기납부세액·회사 지급 일정에 따라 달라집니다. 다음 해 2월은 계산용 가정이며 삼성 확정 입금일이 아닙니다. 보험은 이미 선징수한 금액과 최종 추정 부담의 차액만 별도로 정산합니다. 환급은 주식 수량이나 매도제한 해제액을 늘리지 않습니다.';
const parts=x=>Object.fromEntries(TYPES.map(k=>[k,BONUS_TYPES.includes(k)?x[k]??0:0]));
const accepted=e=>e.type==='opi1'||e.type==='opi2'||e.type==='settlement';
export function bonusView(full){
 const accrual=full.accrual.map(a=>{const gross=parts(a.gross),net=parts(a.net),details=a.details.filter(accepted),stock=a.opi2StockMarketValue??0;return {...a,gross,net,details,grossTotal:sum(Object.values(gross)),netTotal:sum(Object.values(net)),netStock:stock,netCash:sum(Object.values(net))-stock,lockedStock:sum(details.filter(e=>e.type==='opi2').flatMap(e=>e.tranches.filter(t=>t.year>a.year)).map(t=>t.net))};});
 let cumulative=0,beforeCumulative=0;const cashflow=full.cashflow.map(a=>{const details=a.details.filter(accepted),gross=parts(a.gross),net=parts(a.net),taxSettlement=sum(details.filter(t=>t.kind==='tax').map(t=>t.net)),insuranceSettlement=sum(details.filter(t=>t.kind==='insurance').map(t=>t.net)),netBeforeSettlement=sum([net.opi1,net.opi2]),netTotal=sum([netBeforeSettlement,taxSettlement,insuranceSettlement]);return {...a,details,gross,net,netTotal,grossTotal:sum(Object.values(gross)),netBeforeSettlement,taxSettlement,insuranceSettlement,taxRefund:sum(details.filter(t=>t.kind==='tax'&&t.net>0).map(t=>t.net)),taxExtraPayment:-sum(details.filter(t=>t.kind==='tax'&&t.net<0).map(t=>t.net)),cumulative:cumulative=sum([cumulative,netTotal]),cumulativeBeforeSettlement:beforeCumulative=sum([beforeCumulative,netBeforeSettlement])};});
 const events=full.events.filter(accepted),allCash=events.flatMap(e=>[...e.tranches,...(e.settlements??[])]),future=allCash.filter(t=>t.year>full.period.end),open=allCash.filter(t=>t.origin<full.period.start&&t.year>=full.period.start),stock=t=>t.type==='opi2',settlements=future.filter(t=>t.type==='settlement');
 const locked={unpaidStock:sum(future.filter(t=>stock(t)&&t.payYear>full.period.end).map(t=>t.net)),paidLockedStock:sum(future.filter(t=>stock(t)&&t.payYear<=full.period.end).map(t=>t.net)),normalUnpaidCash:sum(future.filter(t=>t.type==='opi1').map(t=>t.net)),settlementAfterPeriod:sum(settlements.map(t=>t.net)),settlementReceivable:sum(settlements.filter(t=>t.net>0).map(t=>t.net)),settlementPayable:-sum(settlements.filter(t=>t.net<0).map(t=>t.net)),settlementEvents:settlements};locked.totalStock=sum([locked.unpaidStock,locked.paidLockedStock]);locked.unpaidCash=sum([locked.normalUnpaidCash,locked.settlementAfterPeriod]);
 const opening={stock:sum(open.filter(stock).map(t=>t.net)),cash:sum(open.filter(t=>!stock(t)).map(t=>t.net))};opening.total=sum(Object.values(opening));
 const totals={grossAccrual:sum(accrual.map(a=>a.grossTotal)),netAccrual:sum(accrual.map(a=>a.netTotal)),netLiquid:cumulative,netLiquidBeforeSettlement:beforeCumulative,taxSettlementInPeriod:sum(cashflow.map(a=>a.taxSettlement)),insuranceSettlementInPeriod:sum(cashflow.map(a=>a.insuranceSettlement)),taxRefundInPeriod:sum(cashflow.map(a=>a.taxRefund)),taxExtraPaymentInPeriod:sum(cashflow.map(a=>a.taxExtraPayment)),settlementInPeriod:sum(cashflow.map(a=>sum([a.taxSettlement,a.insuranceSettlement]))),donation:full.totals.donation};
 const accounting={opening:opening.total,netAccrual:totals.netAccrual,netLiquid:totals.netLiquid,closingStock:locked.totalStock,closingCash:locked.unpaidCash,difference:sum([opening.total,totals.netAccrual,-totals.netLiquid,-locked.totalStock,-locked.unpaidCash])};if(accounting.difference!==0)throw Error('OPI1+OPI2 회계 보존 오류 '+accounting.difference);
 const people=[{...full.people[0],accrual,cashflow,events,opening,locked,totals}];
 return {...full,compensationBasisByYear:Object.fromEntries((full.policyLedger?.rows??[]).map(row=>[row.originYear,referenceSalary([row])])),scope:'OPI1+OPI2',accrual,cashflow,events,people,opening,locked,totals,accounting,fullCompensation:full,settlementNotice:SETTLEMENT_NOTICE};
}
export function bonusPlan(s,scenario){const clean=normalizeSimpleState(structuredClone(s));return bonusView(calculatePlan(clean,scenario));}
export const compareBonus=s=>Object.fromEntries(Object.entries(s.scenarios).map(([k,v])=>[k,bonusPlan(s,v)]));
export function bonusPresets(s){const d=defaults(),opt=structuredClone(d.scenarios.middle);opt.name='낙관 계획 가정 ×1.25';for(const y of years(s))opt.performance[y]=(opt.performance[y]??0)*1.25;return {basic:bonusPlan(s,d.scenarios.middle),conservative:bonusPlan(s,d.scenarios.downturn),optimistic:bonusPlan(s,opt)};}
export function exportBonus(s){
 const clean=normalizeSimpleState(structuredClone(s)),fullExport=exportIntegrated(clean),r=bonusPlan(clean),input=fullExport.input;input.opi2Policy={simpleInput:true,donationRate:clean.opi2Policy.donationRate};
 delete fullExport.assumptions.policy.manualGrossByYear;delete fullExport.assumptions.policy.manualAward;
 fullExport.assumptions.policy.inputMethod='연봉·소속·학술연수·연결 영업이익으로 자동 계산';
 fullExport.assumptions.policy.cashSettlement='소득세 차액: 과세 다음 해 2월 / 보험 차액: 지급 다음 해 4월 (계획용 가정)';
 const data={schemaVersion:2,input,resultModel:'automatic_opi1_opi2_dashboard',scope:'OPI1+OPI2',assumptions:{...fullExport.assumptions,donationTaxCredit:'미반영 (0% 기부 시 기부금과 기부 세액공제 모두 0원)',performanceProxy:'삼성전자 전체 연결 영업이익을 DS 성과급 단순산식의 대용 가정으로 사용; 연결→DS 변환율 없음',incomeAttribution:'사용자 제공 2026-10-07 회사 안내를 모델로 채택; 지급일만으로 귀속을 일반화하지 않음',taxWithholding:'회사 안내에 따른 선징수49.5% 가정; 법정 보편 상여금 세율 아님',taxSettlement:'과세 다음 해 2월 계산용 가정; 삼성 확정 입금일 아님',insuranceSettlement:'다음 해 4월 보험 차액 정산 계획 가정; 실제 회사 일정 미확인'},performanceScenario:r.scenario,compensationMultiples2026:compensationMultiples(r,2026),people:r.people,annualAccrualCompensation:r.accrual,annualLiquidCashflow:r.cashflow,openingCompensationBalance:r.opening,lockedStockAfter2030:{asOf:s.endYear,...r.locked},cashSettlementAfterPeriod:r.locked.settlementEvents,scenarioComparison:Object.fromEntries(Object.entries(compareBonus(clean)).map(([k,v])=>[k,{name:v.scenario.name,scope:v.scope,totals:v.totals,annual:v.cashflow}])),inputPresetComparison:Object.fromEntries(Object.entries(bonusPresets(clean)).map(([k,v])=>[k,{name:v.scenario.name,totals:v.totals}])),totals:r.totals,accounting:r.accounting,fullCompensationSummary:{scope:'월급·고정수당·TAI·PSU 포함 별도 요약',annualAccrual:fullExport.annualAccrualCompensation,annualCashflow:fullExport.annualLiquidCashflow,totals:r.fullCompensation.totals},settlementNotice:SETTLEMENT_NOTICE,disclaimer:fullExport.disclaimer};
 return JSON.parse(JSON.stringify(data,(k,v)=>['policyRow','withholdingAlternatives','shareIncomeCandidates'].includes(k)?undefined:v));
}

// A ledger basis already contains contract salary plus work bonus. Never add work bonus twice.
export function referenceSalary(rows){return sum(rows.map(row=>row.basis!==undefined?row.basis:sum([row.contractSalary??0,row.workBonus??0])));}
export function compensationMultiples(r,year=2026){const denominator=r.compensationBasisByYear?.[year]??referenceSalary((r.fullCompensation?.policyLedger?.rows??[]).filter(row=>row.originYear===year));const a=r.accrual.find(x=>x.year===year),c=r.cashflow.find(x=>x.year===year),ratio=value=>denominator>0&&value!==undefined?value/denominator:null;return {year,denominator,denominatorDefinition:'계약연봉 + 업무성과급 (기존 원장 기준금액을 한 번만 사용, 고정수당 제외)',accrualGross:ratio(a?.grossTotal),accrualNet:ratio(a?.netTotal),liquidNet:ratio(c?.netTotal)};}
